-- Step BC-2: the FLAG FRAME templates — several frames in one drawing.
-- Run by Nathan in the Supabase SQL editor. Safe to re-run.
-- Run AFTER sql/step-bc1, and after the Step AZ / BA / BB files (all live).
--
-- Integrate's own templates, from its Door group "2. Open Out Doors"
-- (docs/integrate-L31115-single-doors.txt, "Coupled multi-frame doorsets"):
--
--    70  (unnamed)                        flag | door | flag    -> sort 100
--          -> GlazePro "Single Door With Flag Lights"
--    71  (unnamed)                        door | flag           -> sort 110
--          -> "Single Door With Flag Light Right"
--    72  (unnamed)                        flag | door           -> sort 120
--          -> "Single Door With Flag Light Left"
--    69  "Doorset with Flag and Fan Lights"                     -> sort 130
--          -> "Single Door With Flag And Fan Lights"
--
-- Each tree was GENERATED by the board's own code
-- (buildCoupledSingleDoorFrame), so each template is exactly what the board
-- would build and assertSaveable passes on it.
--
-- THE MODEL. One item holds a `containerPart` ("Frames", bayTypeId 176,
-- partSpacing -47) with several `assemblyFrameParts` side by side, left to
-- right — Integrate's own storage. `partSpacing -47` is the coupling: each
-- frame starts one jamb (47 mm) before the previous one ends, so template
-- 70's 693 + 995 + 693 set is 2287 mm wide and not 2381. The frames are
-- HEAD-ALIGNED: a flag light is a high side window over a wall, not
-- floor-standing. Every frame is a WHOLE frame — its own jambs, head, cill,
-- dividers and openings — and the labels run on across them (A | B | C).
--
-- WHAT THE BOARD CHOSE, and where it departs from the drawings that were read:
--
--  * template 72's door frame is 998 wide, the same as 71's, so the
--    left-flag and right-flag templates are MIRROR IMAGES of each other.
--    Integrate's own 72 is 1001 / 696 against 71's 998 / 693 — three
--    millimetres that nobody drew on purpose. The brief offered either; this
--    is the one chosen, and it is said out loud in docs/reports/step-bc.md;
--  * a flag frame's own light keeps Integrate's 86 bottom rail; the FANLIGHTS
--    of template 69 take Nathan's 62 (difference 5), so their rails are
--    charged at Utile63x63 rather than 63x96 (difference 7b);
--  * template 69's flag fanlights are TOP HUNG (Integrate operation 15) over
--    a fixed light, and the door frame's fanlight is FIXED over the leaf —
--    which is what makes the flags' top lights 90 install minutes each and
--    the door's 120;
--  * a door leaf is never arched (Step BB).
--
-- NO stored ironmongery list and NO stored surround list, as every GlazePro
-- template since Step AX. Integrate prices NO architrave at all on a
-- container item; Nathan's decision (b) charges ONE set round the whole set,
-- which the allocator does from the container.
--
-- Product "Door" and window_type "Door" on all four: every one of them is a
-- single door. Product and Quantity are both is_required (Step AQ), so the
-- code is looked up BY LABEL and the script fails loudly rather than writing
-- a code that would look set and still fail the check.
--
-- RUN SECTION 0 FIRST.

-- ═══════════════════════════════════════════════════════════════════════════
-- SECTION 0 — read before changing
-- ═══════════════════════════════════════════════════════════════════════════

-- 0a. Every door template as it stands. Expect the ten from Steps AZ / BA /
--     BB and none of this step's four.
SELECT id, name, family, group_name, window_type, sort_order, is_active
FROM   public.drawing_templates
WHERE  family = 'door'
ORDER  BY sort_order, name;

-- 0b. Do any of this step's four names already exist? A re-run updates them
--     in place; anything else here is somebody else's template.
SELECT id, name, sort_order, is_active, updated_at
FROM   public.drawing_templates
WHERE  name IN (
    'Single Door With Flag Lights',
    'Single Door With Flag Light Right',
    'Single Door With Flag Light Left',
    'Single Door With Flag And Fan Lights'
)
ORDER  BY name;

-- 0c. THE CONTAINMENT THIS STEP DEPENDS ON. The brief says both pairs are
--     already live; this is the read that proves it. Expect two rows:
--       drawingItemPart -> containerPart
--       containerPart   -> assemblyFramePart
--     If either is missing, STOP — section 1 adds them, but the reviewer
--     should know it was not there.
SELECT parent_code, child_code, min_count, max_count, sort_order
FROM   part_type_children
WHERE  child_code IN ('containerPart', 'assemblyFramePart')
   OR  parent_code = 'containerPart'
ORDER  BY parent_code, child_code;

-- 0d. The containerPart part type itself.
SELECT code, label, is_container, is_singleton, is_active, sort_order
FROM   part_types
WHERE  code = 'containerPart';

-- 0e. Rule 140, which sql/step-bc1 rewrites. Expect the AFTER values from
--     that file: 'Single Door (Flag Frame)', 240 min per extra frame. If it
--     still reads 'Winglight Frame' at 1 minute, run step-bc1 first.
SELECT sort_order, name, condition, quantity, value, is_active
FROM   public.price_rules
WHERE  id = 'df59375e-6e73-41aa-bb5d-bd2366d12f84';


-- ═══════════════════════════════════════════════════════════════════════════
-- SECTION 1 — the containment, and the four templates
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

-- Belt and braces: the two pairs a multi-frame drawing needs. Both are
-- expected to exist already (SECTION 0c), so this normally changes nothing.
INSERT INTO part_type_children (parent_code, child_code, min_count, max_count, sort_order)
VALUES
  ('drawingItemPart', 'containerPart',     0, 1,    45),
  ('containerPart',   'assemblyFramePart', 1, NULL, 10)
ON CONFLICT (parent_code, child_code) DO NOTHING;

DO $$
