o":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_497d8re","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]},{"key":"flagframe_zc3dut5","part_type":"assemblyFramePart","values":{"width":693,"height":1136,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"flagframe_zc3dut5_light","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_zc3dut5_light_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_zc3dut5_cill","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}]}},{"name":"Single Door With Flag Light Left","sort_order":120,"tree":{"key":"item_nivdhl4","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_okxxs00","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_f2jujfk","part_type":"notesPart","values":{},"children":[]},{"key":"price_lm9rhrb","part_type":"pricePart","values":{},"children":[]},{"key":"frames_iy8ny12","part_type":"containerPart","values":{"bayType