n":[{"key":"doorleaf_ec20l4l_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_6qotoul","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}]}},{"name":"Single Door With Flag And Fan Lights","sort_order":130,"tree":{"key":"item_vo20tm3","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_eb6nwmx","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_bdvrwhy","part_type":"notesPart","values":{},"children":[]},{"key":"price_3e8sbme","part_type":"pricePart","values":{},"children":[]},{"key":"frames_saaz16b","part_type":"containerPart","values":{"bayTypeId":176,"partSpacing":-47,"isCoupledInTheFactory":false,"isBayPoleRequired":false,"hasContinousSubCill":false,"isCornerpostRequired":false},"children":[{"key":"flagframe_6ijexkj","part_type":"assemblyFramePart","values":{"width":650,"height":1632,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"flagframe_6ijexkj_trans","part_type":"transomPart","values":{"offset":348,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"flagframe_6ijexkj_fan","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_6ijexkj_fan_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_6ijexkj_light","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_6ijexkj_light_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_6ijexkj_cill","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]},{"key":"frame_p3cquqw","part_type":"assemblyFramePart","values":{"width":1082,"height":2496,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"trans_fzfhtds","part_type":"transomPart","values":{"offset":348,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"cas_4jm781o","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_4jm781o_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"doorleaf_41h9sjo","part_type":"doorLeafPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","mechanicalClearanceTop":2,"mechanicalClearanceLeft":3,"mechanicalClearanceRight":3,"mechanicalClearanceBottom":3,"archHead":false,"toBeReplaced":true},"children":[{"key":"doorleaf_41h9sjo_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_3p0lyzz","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]},{"key":"flagframe_cvto1v2","part_type":"assemblyFramePart","values":{"width":650,"height":1632,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"flagframe_cvto1v2_trans","part_type":"transomPart","values":{"offset":348,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"flagframe_cvto1v2_fan","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_cvto1v2_fan_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_cvto1v2_light","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_cvto1v2_light_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_cvto1v2_cill","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}]}}]'::jsonb;
  _row         record;
  _tree        jsonb;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'open_out_doors' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''open_out_doors'' — the door profile must exist first';
  END IF;

  SELECT code INTO _single_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'door' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _single_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''Door''';
  END IF;

  -- A template that cannot be saved is worse than no template.
  IF NOT EXISTS (
    SELECT 1 FROM part_type_children
    WHERE parent_code = 'containerPart' AND child_code = 'assemblyFramePart'
  ) THEN
    RAISE EXCEPTION 'A container cannot hold a frame — the containment above did not take';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM part_type_children
    WHERE parent_code = 'assemblyFramePart' AND child_code = 'doorLeafPart'
  ) THEN
    RAISE EXCEPTION 'A frame cannot hold a door leaf — run sql/step-bb1-single-door-containment.sql first';
  END IF;

  -- And a door with no sections prices no timber at all, which would look
  -- like a working template and quote hundreds of pounds short.
  IF NOT EXISTS (
    SELECT 1 FROM parts_catalogue WHERE part_code = 'Utile67x96' AND is_active
  ) THEN
    RAISE EXCEPTION 'The Utile stock sections are missing — run sql/step-az1-utile-section-parts.sql first';
  END IF;

  IF jsonb_array_length(_templates) <> 4 THEN
    RAISE EXCEPTION 'Expected 4 templates in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates) AS x(name text, sort_order int, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_single_code), true);

    IF EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = _row.name) THEN
      UPDATE public.drawing_templates
      SET tree = _tree, default_profile_id = _profile_id, window_type = 'Door',
          sort_order = _row.sort_order, updated_at = now()
      WHERE name = _row.name;
      RAISE NOTICE 'Step BC-2: % updated in place', _row.name;
    ELSE
      INSERT INTO public.drawing_templates
        (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
      VALUES (_row.name, 'door', 'Open Out Doors', 'Door',
              _profile_id, _tree, _row.sort_order, TRUE);
      RAISE NOTICE 'Step BC-2: % created', _row.name;
    END IF;
  END LOOP;
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. All fourteen door templates, with Product and window_type.
SELECT name, group_name, window_type, sort_order, is_active,
       tree #>> '{values,product}'  AS product_code,
       tree #>> '{values,quantity}' AS quantity,
       jsonb_path_exists(tree, '$.**.part_type ? (@ == "containerPart")') AS is_multi_frame
FROM   public.drawing_templates
WHERE  family = 'door'
ORDER  BY sort_order;

-- 2. Each new template's frames, left to right, with their sizes. Expect
--      Flag Lights        693x1136 | 995x2101 | 693x1136
--      Flag Light Right   998x2101 | 693x1136
--      Flag Light Left    693x1136 | 998x2101
--      Flag And Fan       650x1632 | 1082x2496 | 650x1632
SELECT t.name,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "assemblyFramePart")')) AS frames,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "containerPart")'))     AS containers,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "doorLeafPart")'))      AS leaves,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "casementSashPart")'))  AS sashes,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "cillPart")'))          AS cills,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "transomPart")'))       AS transoms
FROM   public.drawing_templates t
WHERE  t.name LIKE 'Single Door With Flag%'
ORDER  BY t.sort_order;

-- 3. The container's own values: partSpacing -47 on every one of them.
SELECT t.name,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.partSpacing') v) AS part_spacing,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.bayTypeId') v)   AS bay_type
FROM   public.drawing_templates t
WHERE  t.name LIKE 'Single Door With Flag%'
ORDER  BY t.sort_order;

-- 4. The fixed-sash rails: a flag's own light 86, template 69's fanlights 62,
--    and every sash FIXED except 69's two top-hung flags.
SELECT t.name,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(t.tree, '$.**.values ? (@.btmRailShapeId == "stepped" && @.mechanicalClearanceTop == 1).bottomHeight') v) AS sash_rails,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(t.tree, '$.**.values ? (@.mechanicalClearanceTop == 1).operation') v) AS sash_operations
FROM   public.drawing_templates t
WHERE  t.name LIKE 'Single Door With Flag%'
ORDER  BY t.sort_order;

-- 5. None of the four carries a stored surround or ironmongery list, and all
--    four are utile. Expect NULL, NULL, utile.
SELECT t.name,
       t.tree #> '{values,surroundLines}' AS surrounds,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.ironmongeryLines') v) AS ironmongery,
       t.tree #>> '{values,sashMaterialId}' AS material
FROM   public.drawing_templates t
WHERE  t.name LIKE 'Single Door With Flag%'
ORDER  BY t.sort_order;


